hudson.tasks.Shell.command:
#!/bin/bash # shellcheck disable=SC2154 # stack_s3_bucket, HPDS_VARIANT, ... are provided by Jenkins set -e
# A properties file from an earlier build must never reach the deploy step. rm -f staging_deploy.properties
# Stages the HPDS data named in build-spec.json (release-control checkout in the workspace) into the stack bucket. # HPDS_VARIANT = both (auth, then open), auth or open. Run by hand; Check For Updates only checks that this was done. # Per variant the source URL and the deploy key come from build-spec.json, exactly as Check For Updates computes them. # source URL ends with .tar -> legacy path: download the tar, (open: remove concepts), re-tar, upload. # source URL is a dataset prefix (ends with /) -> per-file staging driven by its manifest.json; the source is read with # curated-datasets-s3-role and every file is streamed through this host into the stack bucket (instance role). # A variant that is already staged is skipped, never overwritten. # DEPLOY_TO_STAGING_STACK=true: once both variants are staged and the checks pass, write staging_deploy.properties (the three # deploy keys); the SystemGroovy step after this one then starts the job HPDS Data - Deploy to Staging Stack with them. That job # takes the locks, resolves the staging stack and deploys. This step looks up no stack. # Contract: bdc-hpds-pheno-release/1 (manifest.json) and bdc-hpds-deploy/1 (manifest.tsv).
refuse() { echo "REFUSED: $*" >&2 exit 1 }
case "${HPDS_VARIANT}" in both) variants="auth open" ;; auth) variants="auth" ;; open) variants="open" ;; *) refuse "unknown HPDS_VARIANT '${HPDS_VARIANT}' (expected both, auth or open)" ;; esac
case "${DEPLOY_TO_STAGING_STACK:-false}" in true) deploy_to_staging=true ;; false) deploy_to_staging=false ;; *) refuse "unknown DEPLOY_TO_STAGING_STACK '${DEPLOY_TO_STAGING_STACK}' (expected true or false)" ;; esac
[ -n "${stack_s3_bucket}" ] || refuse "stack_s3_bucket is not set" [ -f build-spec.json ] || refuse "build-spec.json not found in the release-control checkout"
# ---- shared with the other HPDS job (Check For Updates / HPDS Data - Stage to Stack Bucket): keep this block identical ---- dataset_marker="/data/hpds/pheno/datasets/"
# ListBucket on data/* is granted while HeadObject on a missing key may answer 403, so list first. key_exists() { local key="$1" out if out=$(aws s3api list-objects-v2 --bucket "${stack_s3_bucket}" --prefix "${key}" --output json 2> /dev/null); then # jq 1.6 -e exits 0 on empty input: an empty listing must mean "not there" [ -n "${out}" ] || return 1 printf '%s' "${out}" | jq -e --arg k "${key}" 'any(.Contents[]?; .Key == $k)' > /dev/null else aws s3api head-object --bucket "${stack_s3_bucket}" --key "${key}" > /dev/null 2>&1 fi }
# Commit that last changed the line of build-spec.json that holds the given field. # A boundary commit (root or shallow clone) is blamed as "^<hash>"; the marker is not part of the hash. blame_commit() { local key key=$(git blame --abbrev=39 build-spec.json | grep "$1" | cut -f 1 -d ' ') echo "${key#^}" }
# Deploy key = blame commit; must look like a git hash (7-40 hex) because it becomes an S3 key segment. deploy_key() { local key key=$(blame_commit "$1") if [ -z "${key}" ]; then echo "ERROR: no line for $1 in build-spec.json" >&2 exit 1 fi if ! [[ "${key}" =~ ^[0-9a-f]{7,40}$ ]]; then echo "ERROR: blame commit '${key}' for $1 is not a git hash" >&2 exit 1 fi echo "${key}" }
spec_url() { jq -r --arg f "$1" '.[$f] // ""' build-spec.json | tr -d '[:space:]' }
is_dataset_prefix() { case "$1" in *"${dataset_marker}"*) return 0 ;; esac return 1 }
# Dataset prefixes carry both variants in one dataset: the two URLs must be the same. require_identical_dataset_urls() { local auth_url open_url auth_url=$(spec_url source_dataset_s3_url) open_url=$(spec_url source_destigmatized_dataset_s3_url) if is_dataset_prefix "${auth_url}" || is_dataset_prefix "${open_url}"; then if [ "${auth_url}" != "${open_url}" ]; then echo "ERROR: source_dataset_s3_url (${auth_url}) and source_destigmatized_dataset_s3_url (${open_url}) must be identical for a dataset prefix" >&2 exit 1 fi fi }
# is_staged <deploy key> <stage prefix> <legacy tar name> # Staged = data/<key>/<stage prefix>manifest.tsv exists (per-file staging, written last) # or data/<key>/<legacy tar name>.tar exists (legacy .tar staging). is_staged() { key_exists "data/$1/$2manifest.tsv" || key_exists "data/$1/$3.tar" } # ---- end of shared block ----
require_identical_dataset_urls
sha256_of() { if command -v sha256sum > /dev/null 2>&1; then sha256sum "$1" | cut -d ' ' -f 1 else shasum -a 256 "$1" | cut -d ' ' -f 1 fi }
# variant_setup <auth|open>: sets variant, stage_prefix, legacy_name, remove_concepts, deploy_key_value, source_url, stage_key_prefix variant_setup() { local field variant="$1" case "${variant}" in auth) field=source_dataset_s3_url stage_prefix="javabins_rekeyed/" legacy_name="javabins_rekeyed" remove_concepts=false ;; open) field=source_destigmatized_dataset_s3_url stage_prefix="destigmatized_javabins_rekeyed/" legacy_name="destigmatized_javabins_rekeyed" remove_concepts=true ;; esac deploy_key_value=$(deploy_key "${field}") source_url=$(spec_url "${field}") stage_key_prefix="data/${deploy_key_value}/${stage_prefix}" install_path="" }
# validate_source: the source URL of the current variant must be an s3 URL ending in .tar (legacy) or / (dataset prefix). # Sets install_path. validate_source() { [[ "${source_url}" =~ ^s3://[a-z0-9][a-z0-9.-]*/[A-Za-z0-9._/=+%:-]+$ ]] || refuse "${variant}: source URL '${source_url}' in build-spec.json is not an s3:// object or prefix URL" if [[ "${source_url}" == *.tar ]]; then install_path=legacy elif [[ "${source_url}" == */ ]]; then install_path=dataset else refuse "${variant}: source URL '${source_url}' must end with .tar (legacy) or / (dataset prefix)" fi }
### Source role: one definition for both paths. The legacy path assumes it with Bash_Functions (assume_role / reset_role); the ### dataset path reads the source through an AWS CLI profile that assumes it (see setup_source_profile). curated_datasets_s3_role="${curated_datasets_s3_role:-arn:aws:iam::515157839325:role/curated-datasets-s3-role}" src_cfg=""
# Profile hpds-source in a private config file: the CLI itself assumes the role (credentials from the instance metadata) and renews # the session, so no credential passes through this shell, an environment variable or a command line. setup_source_profile() { local session [ -z "${src_cfg}" ] || return 0 [[ "${curated_datasets_s3_role}" =~ ^arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9+=,.@_/-]+$ ]] || refuse "curated_datasets_s3_role '${curated_datasets_s3_role}' is not a role ARN" # Role session name: job and build number, at most 64 characters of [A-Za-z0-9+=,.@_-]; the end (build number) is kept. session="$(printf '%s-%s' "${JOB_NAME:-hpds-stage}" "${BUILD_NUMBER:-0}" | tr -c 'A-Za-z0-9+=,.@_-' '-')" [ "${#session}" -le 64 ] || session="${session: -64}" src_cfg="$(mktemp "${TMPDIR:-/tmp}/hpds-source-profile.XXXXXX")" || refuse "cannot create the AWS profile file for ${curated_datasets_s3_role}" trap 'rm -f "${src_cfg}"' EXIT chmod 600 "${src_cfg}" { echo "[profile hpds-source]" echo "role_arn = ${curated_datasets_s3_role}" echo "credential_source = Ec2InstanceMetadata" echo "role_session_name = ${session}" echo "duration_seconds = 3600" } > "${src_cfg}" }
# aws as the source role: for reads of the source bucket only. An explicit --profile makes the CLI ignore any AWS_* keys in the # environment (a profile named in the environment would not); the config-file prefix assignment lasts for this one command and is never exported, # so everything else (stack bucket, lists, heads) keeps the default instance identity. src_aws() { AWS_CONFIG_FILE="${src_cfg}" aws --profile hpds-source "$@" }
# Before anything is written: can the source role be assumed? check_source_access() { setup_source_profile src_aws sts get-caller-identity --output text > /dev/null < /dev/null \ || refuse "cannot assume ${curated_datasets_s3_role} to read ${source_url}" }
# stream_copy <source s3 URL> <destination s3 URL> <bytes>: read as the source role, write as the instance role. Either side of # the pipe failing fails the copy. --expected-size is needed by the CLI for streams over 50 GB. stream_copy() { local src="$1" dest="$2" bytes="$3" ( set -o pipefail src_aws s3 cp "${src}" - --only-show-errors < /dev/null \ | aws s3 cp - "${dest}" --sse AES256 --expected-size "${bytes}" --only-show-errors ) || refuse "copy of ${src} to ${dest} failed" }
### Per-file staging from a dataset prefix. No docker. Reads of the source bucket use curated-datasets-s3-role (src_aws), writes to ### the stack bucket the instance role. IAM needed (see the job description): # curated-datasets-s3-role, source bucket: s3:GetObject on data/hpds/pheno/datasets/*; its trust policy allows the instance role # instance role, stack bucket: s3:ListBucket + s3:GetObject + s3:PutObject on data/*, and sts:AssumeRole on the source role stage_dataset() { local work=dataset_work dataset_id manifest_sha e_src e_dest e_bytes e_sha e_etag head_json got_bytes expected_rows written_rows rm -rf "${work}" mkdir -p "${work}"
check_source_access src_aws s3 cp "${source_url}manifest.json" "${work}/manifest.json" --only-show-errors < /dev/null \ || refuse "cannot read ${source_url}manifest.json (not a released dataset prefix?)" # jq 1.6 -e exits 0 on empty input, so the checks below need a non-empty file [ -s "${work}/manifest.json" ] || refuse "${source_url}manifest.json is empty"
jq -e --arg v "${variant}" ' def okpath: type == "string" and test("^[A-Za-z0-9._/-]+$") and (startswith("/") | not) and (endswith("/") | not) and (test("//") | not) and (test("(^|/)\\.{1,2}(/|$)") | not); .schema == "bdc-hpds-pheno-release/1" and (.dataset_id | type == "string" and test("^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{4}Z$")) and (.variants[$v] | type == "array" and length > 0) and all(.variants[$v][]; (.src | okpath) and (.dest | okpath) and (.bytes | type == "number" and . >= 0 and . == floor) and (.sha256 == null or (.sha256 | type == "string" and test("^[0-9a-f]{64}$"))) and (.etag == null or (.etag | type == "string" and test("^[!-~]*$")))) and ([.variants[$v][].dest] | length) == ([.variants[$v][].dest] | unique | length) and any(.variants[$v][]; .dest == "metadata.json") and any(.variants[$v][]; .dest == "columnMeta.javabin") ' "${work}/manifest.json" > /dev/null || refuse "manifest.json is not a valid bdc-hpds-pheno-release/1 manifest with a usable '${variant}' variant"
if [ "${variant}" = "open" ]; then jq -e ' (.removal.open_columnmeta_sha256 | type == "string" and length > 0) and (.removal.full_columnmeta_sha256 | type == "string" and length > 0) and (.removal.open_columnmeta_sha256 != .removal.full_columnmeta_sha256) and (((.removal.full_columnmeta_content_sha256 | type) == "string" and (.removal.open_columnmeta_content_sha256 | type) == "string" and .removal.full_columnmeta_content_sha256 == .removal.open_columnmeta_content_sha256) | not) and all(.variants.open[] | select(.dest == "columnMeta.javabin"); .src != "columnMeta.javabin") ' "${work}/manifest.json" > /dev/null || refuse "open variant would ship the full columnMeta.javabin (concepts were not removed, or full and open columnMeta contents are identical)" else jq -e 'all(.variants.auth[]; (.src | startswith("open/")) | not)' "${work}/manifest.json" > /dev/null \ || refuse "auth variant must not use files from open/" fi
dataset_id="$(jq -r '.dataset_id' "${work}/manifest.json")" manifest_sha="$(sha256_of "${work}/manifest.json")"
{ echo "# bdc-hpds-deploy/1" echo "# variant=${variant}" echo "# dataset_id=${dataset_id}" echo "# source=${source_url}" echo "# manifest_sha256=${manifest_sha}" printf 'dest\tbytes\tsha256\tetag\tsrc\n' } > "${work}/manifest.tsv"
jq -r --arg v "${variant}" '.variants[$v][] | [.src, .dest, (.bytes | tostring), (.sha256 // "-"), (.etag // "-")] | @tsv' \ "${work}/manifest.json" > "${work}/entries.tsv"
while IFS=$'\t' read -r e_src e_dest e_bytes e_sha e_etag; do echo "staging ${e_src} -> ${e_dest} (${e_bytes} bytes)" # Every aws call in this loop reads /dev/null or the stream pipe: the loop reads entries.tsv on stdin and a CLI that read it # would end the loop early. stream_copy "${source_url}${e_src}" "s3://${stack_s3_bucket}/${stage_key_prefix}${e_dest}" "${e_bytes}" head_json="$(aws s3api head-object --bucket "${stack_s3_bucket}" --key "${stage_key_prefix}${e_dest}" < /dev/null)" got_bytes="$(printf '%s' "${head_json}" | jq -r '.ContentLength')" [ "${got_bytes}" = "${e_bytes}" ] || refuse "${e_dest}: staged ${got_bytes} bytes, manifest says ${e_bytes}" printf '%s\t%s\t%s\t%s\t%s\n' "${e_dest}" "${e_bytes}" "${e_sha}" "${e_etag}" "${e_src}" >> "${work}/manifest.tsv" # fence_mapping.json belongs to the auth variant (PSAMA reads the auth key's); the open variant must not replace it. if [ "${e_dest}" = "metadata.json" ] && [ "${variant}" = auth ]; then stream_copy "${source_url}${e_src}" "s3://${stack_s3_bucket}/data/${deploy_key_value}/fence_mapping.json" "${e_bytes}" fence_json="$(aws s3api head-object --bucket "${stack_s3_bucket}" --key "data/${deploy_key_value}/fence_mapping.json" < /dev/null)" fence_bytes="$(printf '%s' "${fence_json}" | jq -r '.ContentLength')" [ "${fence_bytes}" = "${e_bytes}" ] || refuse "fence_mapping.json: staged ${fence_bytes} bytes, metadata.json has ${e_bytes}" fi done < "${work}/entries.tsv"
# Never publish a manifest.tsv that lists fewer files than the variant has. expected_rows="$(jq -r --arg v "${variant}" '.variants[$v] | length' "${work}/manifest.json")" written_rows="$(tail -n +7 "${work}/manifest.tsv" | wc -l | tr -d ' ')" [ "${written_rows}" = "${expected_rows}" ] || refuse "manifest.tsv has ${written_rows} data rows, the ${variant} variant has ${expected_rows} entries; not uploading it"
# manifest.tsv last: its presence marks the stage prefix complete and immutable. aws s3 cp "${work}/manifest.tsv" "s3://${stack_s3_bucket}/${stage_key_prefix}manifest.tsv" --sse AES256 --only-show-errors < /dev/null echo "Staged ${variant} from ${source_url} (dataset ${dataset_id}) to s3://${stack_s3_bucket}/${stage_key_prefix}" }
### Legacy .tar path (unchanged behaviour; output name and concept removal derive from the variant). bash_functions_loaded=false etl_image_loaded=false
# assume_role, reset_role and get_stack come from the Bash_Functions job workspace; only the legacy path needs them. load_bash_functions() { local source_scripts_folder="${JENKINS_HOME}/workspace/Bash_Functions/" script_file [ "${bash_functions_loaded}" = false ] || return 0 ls -la "$source_scripts_folder" # Iterate through the files in the folder and source them for script_file in "$source_scripts_folder"*.sh; do chmod +x "$script_file" if [ -f "$script_file" ] && [ -x "$script_file" ]; then echo "sourcing $script_file" # shellcheck source=/dev/null source "$script_file" fi done bash_functions_loaded=true }
# The open variant removes concepts with the ETL image in docker. load_etl_image() { local stack [ "${etl_image_loaded}" = false ] || return 0 stack=$(get_stack "staging")
### Build ETL Image aws s3 --sse=AES256 cp "s3://${stack_s3_bucket}/${stack}/containers/pic-sure-hpds-etl.tar.gz" pic-sure-hpds-etl.tar.gz --no-progress
HPDS_ETL_IMAGE=$(docker load < ./pic-sure-hpds-etl.tar.gz | cut -d ' ' -f 3) echo "$HPDS_ETL_IMAGE" ls -alh "$(pwd)" etl_image_loaded=true }
stage_legacy() { load_bash_functions rm -rf local/hpds local/source mkdir -p local/hpds/ mkdir -p local/source/
if [ "${remove_concepts}" = "true" ]; then load_etl_image fi
### Pull data set to rekey. assume_role "${curated_datasets_s3_role}"
aws s3 cp "${source_url}" local/source/javabins.tar --no-progress
### Try extracting as compressed tar if tar -xzvf local/source/javabins.tar -C local/source; then echo "Extracted compressed tar file." else echo "Compressed extraction failed, trying non-compressed..." if tar -xvf local/source/javabins.tar -C local/source; then echo "Extracted non-compressed tar file." else echo "Error: Extraction failed for both compressed and non-compressed tar files." exit 1 fi fi
reset_role
# For caution replicate data into local/hpds as the loader used to write there. cp -r local/source/* local/hpds/
### Open variant: remove concepts if [ "${remove_concepts}" = "true" ]; then # RemoveConceptFromMetadata reads the data set in /opt/local/hpds. # add concepts to remove to /opt/local/hpds that contains the list of concepts to destigmatize cp local/source/conceptsToRemove.txt local/hpds/ docker run -e HEAPSIZE=20480 -e JAVA_OPTS="-Xms4g" -i -v "${WORKSPACE}"/local:/opt/local:Z -e LOADER_NAME=RemoveConceptFromMetadata "$HPDS_ETL_IMAGE" fi
( cd "${WORKSPACE}"/local/hpds/ # Leave the data set artifact as non-compressed for the rest of it's lifecycle tar -cvf "${legacy_name}.tar" -- *.javabin encryption_key metadata.json # fence_mapping.json is the auth variant's only (see stage_dataset). It goes first: the tar is the "staged" marker, so it # must be the last upload. if [ "${variant}" = auth ]; then aws s3 --sse=AES256 cp metadata.json "s3://${stack_s3_bucket}/data/${deploy_key_value}/fence_mapping.json" fi aws s3 --sse=AES256 cp "${legacy_name}.tar" "s3://${stack_s3_bucket}/data/${deploy_key_value}/${legacy_name}.tar" --quiet ) }
# data/<auth key>/fence_mapping.json is what the PSAMA deploy reads. Stack bucket only, instance role (no source credentials exist # here: src_aws is the only place that passes them on). Called with the auth variant set up and already staged. # Staged per-file: a missing mapping is restored from the staged metadata.json. Staged as a legacy tar: its metadata.json is inside # the tar and cannot be reached from here, so that is refused. ensure_fence_mapping() { local fence_key="data/${deploy_key_value}/fence_mapping.json" if key_exists "${fence_key}"; then return 0 fi if ! key_exists "${stage_key_prefix}manifest.tsv"; then refuse "auth data for deploy key ${deploy_key_value} is staged as a legacy tar and ${fence_key} is missing; it cannot be restored in place: restage under a new deploy key (commit a change to the source URL lines of build-spec.json, then run this job)" fi aws s3 cp "s3://${stack_s3_bucket}/${stage_key_prefix}metadata.json" "s3://${stack_s3_bucket}/${fence_key}" --sse AES256 --only-show-errors \ || refuse "cannot restore ${fence_key} from ${stage_key_prefix}metadata.json" key_exists "${fence_key}" || refuse "${fence_key} is still missing after the restore" echo "fence_mapping.json restored from the staged metadata.json" }
# Plan first: work out the keys and validate the source of every variant that still has to be staged, # so a bad build-spec.json is refused before anything is copied. for variant in ${variants}; do variant_setup "${variant}" if ! is_staged "${deploy_key_value}" "${stage_prefix}" "${legacy_name}"; then validate_source fi done
summary="" for variant in ${variants}; do variant_setup "${variant}" if is_staged "${deploy_key_value}" "${stage_prefix}" "${legacy_name}"; then echo "${variant}: already staged, skipping (deploy key ${deploy_key_value})" if [ "${variant}" = auth ]; then ensure_fence_mapping fi summary="${summary}${variant}: already staged (deploy key ${deploy_key_value})"$'\n' continue fi validate_source echo "${variant}: staging ${source_url} as deploy key ${deploy_key_value}" if [ "${install_path}" = dataset ]; then stage_dataset else stage_legacy fi summary="${summary}${variant}: staged (deploy key ${deploy_key_value})"$'\n' done
### Optional deploy to the staging stack (DEPLOY_TO_STAGING_STACK=true). # The deploy needs the data of BOTH variants and the fence mapping, whichever variant was requested here. Everything is checked # first; staging_deploy.properties is written only when every check passed. The SystemGroovy step after this shell step starts # the deploy job from that file alone. No stack is looked up here: the deploy job resolves the staging stack under its locks. prepare_staging_deploy() { local v auth_key="" open_key="" genomic_key props_tmp="staging_deploy.properties.tmp"
for v in auth open; do variant_setup "${v}" is_staged "${deploy_key_value}" "${stage_prefix}" "${legacy_name}" \ || refuse "staging deploy needs the ${v} data, which is not staged for deploy key ${deploy_key_value}; run this job with HPDS_VARIANT=${v} (or both) first" if [ "${v}" = auth ]; then auth_key="${deploy_key_value}"; else open_key="${deploy_key_value}"; fi done
# PSAMA copies data/<auth key>/fence_mapping.json into its container: restore it when the auth data is staged per-file. variant_setup auth ensure_fence_mapping
genomic_key=$(blame_commit source_genomic_dataset_s3_url) [ -n "${genomic_key}" ] || refuse "staging deploy: no source_genomic_dataset_s3_url line in build-spec.json" [[ "${genomic_key}" =~ ^[0-9a-f]{7,40}$ ]] || refuse "staging deploy: blame commit '${genomic_key}' for source_genomic_dataset_s3_url is not a git hash"
{ echo "auth_key=${auth_key}" echo "open_key=${open_key}" echo "genomic_key=${genomic_key}" } > "${props_tmp}" mv "${props_tmp}" staging_deploy.properties echo "staging deploy: checks passed; the next build step starts HPDS Data - Deploy to Staging Stack with the deploy keys (auth ${auth_key}, open ${open_key}, genomic ${genomic_key})" }
printf '%s' "${summary}" if [ "${deploy_to_staging}" = true ]; then prepare_staging_deploy else echo "Next: run Check For Updates (or wait for the scheduled run) to deploy." fi

script.script:
import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*

// Starts HPDS Data - Deploy to Staging Stack, only when the shell step above asked for it by writing staging_deploy.properties
// (auth_key, open_key, genomic_key) after all of its checks passed. The deploy job takes the locks, resolves the staging stack
// and deploys. There is no stack parameter and no stack lookup here.
def deployJobName = "HPDS Data - Deploy to Staging Stack"
def propsFile = build.workspace?.child("staging_deploy.properties")
if (propsFile == null || !propsFile.exists()) {
    if ("true".equals(build.buildVariables?.get("DEPLOY_TO_STAGING_STACK"))) {
        throw new AbortException("DEPLOY_TO_STAGING_STACK is true but staging_deploy.properties is missing; nothing was deployed")
    }
    println "staging deploy: not requested"
    return
}
// The file is only ever written for a build that asked for the deploy; anything else is not trusted.
if (!"true".equals(build.buildVariables?.get("DEPLOY_TO_STAGING_STACK"))) {
    throw new AbortException("staging_deploy.properties exists but DEPLOY_TO_STAGING_STACK is not true; nothing was deployed")
}

def props = new Properties()
props.load(new StringReader(propsFile.readToString()))

def need = { String name, String pattern ->
    String value = (props.getProperty(name) ?: "").trim()
    if (!(value ==~ pattern)) {
        throw new AbortException("staging_deploy.properties: " + name + " is missing or malformed; nothing was deployed")
    }
    return value
}
String authKey = need("auth_key", /[0-9a-f]{7,40}/)
String openKey = need("open_key", /[0-9a-f]{7,40}/)
String genomicKey = need("genomic_key", /[0-9a-f]{7,40}/)

// Schedules a job and waits for it. Parameters that are not given keep their default value, as in a manual build.
def deploy = { String jobName, Map<String, String> given ->
    def job = Jenkins.instance.getItemByFullName(jobName)
    if (job == null) {
        throw new AbortException(jobName + " does not exist; nothing was deployed")
    }
    def values = []
    job.getProperty(ParametersDefinitionProperty)?.parameterDefinitions?.each { pd ->
        if (!given.containsKey(pd.name)) {
            def dv = pd.getDefaultParameterValue()
            if (dv != null) {
                values << dv
            }
        }
    }
    given.each { k, v -> values << new StringParameterValue(k, v) }
    println "staging deploy: starting " + jobName
    def future = job.scheduleBuild2(0, new CauseAction(new Cause.UpstreamCause(build)), new ParametersAction(values))
    if (future == null) {
        throw new AbortException(jobName + " could not be scheduled; nothing was deployed")
    }
    def started = future.waitForStart()
    println "staging deploy: " + jobName + " #" + started.getNumber() + " (" + started.getUrl() + ")"
    def run = future.get()
    if (run.getResult() != Result.SUCCESS) {
        throw new AbortException(jobName + " #" + run.getNumber() + " failed (" + run.getResult() + ")")
    }
    println "staging deploy: " + jobName + " #" + run.getNumber() + " succeeded"
}

deploy(deployJobName, [
    DATA_S3_OBJECT_KEY                 : authKey,
    DESTIGMATIZED_DATASET_S3_OBJECT_KEY: openKey,
    GENOMIC_DATASET_S3_OBJECT_KEY      : genomicKey,
])

println "Deployed to the staging stack only. A later Deployment Pipeline run rebuilds the staging stack from build-spec.json."
